// Browser regression using real page rasters generated by backend/tests/test_pdf_source.py.
const { createServer } = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const { chromium } = require(process.env.PLAYWRIGHT_MODULE || 'playwright');
const root = path.resolve(__dirname, '../dist');
const out = path.resolve(__dirname, '../../artifacts/pdf-review');
const manifest = JSON.parse(fs.readFileSync(path.join(out, 'manifest.json')));
const server = createServer((req, res) => {
  let file = path.join(root, new URL(req.url, 'http://localhost').pathname);
  if (!file.startsWith(root)) { res.writeHead(403).end(); return; }
  if (!fs.existsSync(file) || fs.statSync(file).isDirectory()) file = path.join(root, 'index.html');
  res.setHeader('Content-Type', ({ '.js': 'text/javascript', '.css': 'text/css', '.html': 'text/html' })[path.extname(file)] || 'application/octet-stream');
  res.end(fs.readFileSync(file));
});
(async () => {
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  try {
    const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
    const errors = [];
    page.on('pageerror', error => errors.push(error.message));
    let failPages = false;
    let sourceRequests = 0;
    const units = [
      { id: 'u-1', title: 'Receiver architecture', semantic_role: 'principle', source_page: 1 },
      { id: 'u-2', title: 'Signal-to-noise ratio equation', semantic_role: 'formula', source_page: 2 },
      { id: 'u-3', title: 'Measurement image', semantic_role: 'example', source_page: 3 },
    ].map(unit => ({ ...unit, document_id: 'doc-1', filename: 'Hybrid_ADC_Receiver.pdf', content: 'Knowledge extraction is reviewed separately from the original PDF.', source_text: 'Auxiliary extracted text for this page.', confidence: .95, importance: 'core', lifecycle: 'PENDING_REVIEW' }));
    await page.route('**/api/**', async route => {
      const url = new URL(route.request().url());
      if (url.pathname === '/api/documents') return route.fulfill({ json: [{ id: 'doc-1', filename: 'Hybrid_ADC_Receiver.pdf', enabled: true }] });
      if (url.pathname === '/api/knowledge-units') return route.fulfill({ json: units });
      if (url.pathname.startsWith('/api/knowledge-units/')) {
        const unit = units.find(unit => url.pathname.endsWith(unit.id));
        // Delayed selection tests stale-response protection in the review workspace.
        if (unit?.id === 'u-2') await new Promise(resolve => setTimeout(resolve, 250));
        return route.fulfill({ json: unit });
      }
      if (url.pathname.endsWith('/source')) { sourceRequests++; return route.fulfill({ json: manifest }); }
      if (url.pathname.includes('/pages/')) {
        if (failPages) return route.fulfill({ status: 404, json: { detail: '原始 PDF 文件不存在，请重新上传原文件' } });
        const number = Number(url.pathname.split('/').pop());
        return route.fulfill({ contentType: 'image/png', body: fs.readFileSync(path.join(out, `fixture-page-${number}.png`)) });
      }
      return route.fulfill({ json: [] });
    });
    await page.goto(`http://127.0.0.1:${server.address().port}/review`);
    const paper = page.locator('.paper img');
    await paper.waitFor();
    await page.waitForFunction(() => document.querySelector('.paper img')?.complete);
    assert.ok((await paper.getAttribute('alt')).includes('第 1 页'));
    await page.screenshot({ path: path.join(out, 'review-desktop.png'), fullPage: true });
    await page.getByRole('button', { name: /Signal-to-noise ratio equation/ }).click();
    await page.waitForFunction(() => document.querySelector('.paper img')?.alt.includes('第 2 页'));
    await page.getByRole('button', { name: '下一页 PDF', exact: true }).click();
    await page.waitForFunction(() => document.querySelector('.paper img')?.alt.includes('第 3 页'));
    await page.getByRole('button', { name: '定位知识点', exact: true }).click();
    await page.waitForFunction(() => document.querySelector('.paper img')?.alt.includes('第 2 页'));
    assert.equal(sourceRequests, 1, 'Selecting units in one PDF should reuse its manifest');
    await page.getByText('提取文本（辅助）', { exact: true }).click();
    assert.ok(await page.getByText('Auxiliary extracted text for this page.', { exact: true }).isVisible());
    await page.getByText('PDF 原稿', { exact: true }).click();
    await page.getByRole('button', { name: '大图阅读', exact: true }).click();
    await paper.waitFor();
    await page.waitForFunction(() => document.querySelector('.paper img')?.complete);
    assert.ok(await page.locator('.pdf-viewer.expanded').isVisible());
    await page.screenshot({ path: path.join(out, 'review-expanded.png'), fullPage: true });
    await page.keyboard.press('Escape');
    assert.equal(await page.locator('.pdf-viewer.expanded').count(), 0);
    await page.locator('.zoom-select').click();
    await page.getByText('放大 150%', { exact: true }).click();
    await paper.waitFor();
    assert.equal(await page.locator('.paper').evaluate(el => el.style.width), '150%');
    await page.locator('.zoom-select').click();
    await page.getByText('适合宽度', { exact: true }).click();
    for (const width of [1280, 768, 390]) {
      await page.setViewportSize({ width, height: 900 });
      await page.waitForTimeout(350);
      assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1), `No horizontal overflow at ${width}px`);
      await page.screenshot({ path: path.join(out, `review-${width}.png`), fullPage: true });
    }
    await page.setViewportSize({ width: 1920, height: 1080 });
    await page.getByRole('button', { name: /Signal-to-noise ratio equation/ }).click();
    await page.getByRole('button', { name: /Measurement image/ }).click();
    await page.waitForTimeout(600);
    assert.ok((await paper.getAttribute('alt')).includes('第 3 页'), 'Slow previous selection must not replace the current page');
    failPages = true;
    await page.reload();
    await page.getByText('原始 PDF 文件不存在，请重新上传原文件', { exact: true }).waitFor();
    assert.equal(await page.locator('.paper').count(), 0);
    await page.getByRole('button', { name: '查看提取文本', exact: true }).click();
    assert.ok(await page.locator('.source-body').isVisible());
    await page.getByText('PDF 原稿', { exact: true }).click();
    failPages = false;
    await page.getByRole('button', { name: '重新加载', exact: true }).click();
    await paper.waitFor();
    assert.deepEqual(errors, []);
    console.log('PASS: PDF original rendering, unit/page navigation, source location, manifest reuse, auxiliary text, zoom, expanded reading, 4 viewports, stale selection, missing original and retry.');
  } finally { await browser.close(); server.close(); }
})().catch(error => { console.error(error); server.close(); process.exitCode = 1; });
